using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
int n; cin >> n;
if (n <= 1) cout << "Today, I ate " << n << " apple.\n";
else cout << "Today, I ate " << n << " apples.\n";
    return 0;
}
```

### 易错点

以原题固定句型为准，零也走单数分支。

