void dfs(int start,int chosen,int sum){
    if(chosen==k){answer+=prime(sum);return;}
    int need=k-chosen;
    for(int i=start;i<=n-need;++i)dfs(i+1,chosen+1,sum+a[i]);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
